import React, { useState, useEffect } from "react";
import { fetchAuditQueue } from "../api";

function AuditQueueModal({ isOpen, onClose }) {
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isOpen) {
      loadRecords();
    }
  }, [isOpen]);

  const loadRecords = async () => {
    setLoading(true);
    try {
      const data = await fetchAuditQueue();
      setRecords(data.records || []);
    } catch (err) {
      console.error("Failed to load audit queue:", err);
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="modal-overlay">
      <div className="modal-content glass">
        <div className="modal-header">
          <div>
            <h2>📋 Human-in-the-Loop Audit Queue</h2>
            <p className="card-sub">Active Learning Registry for unclassified chemical tokens.</p>
          </div>
          <button className="btn-close" onClick={onClose}>&times;</button>
        </div>

        <div className="modal-body">
          {loading ? (
            <div className="loading-state">
              <div className="spinner"></div>
              <p>Loading audit queue...</p>
            </div>
          ) : records.length === 0 ? (
            <div className="empty-notice">
              <span>✅</span>
              <p>Audit queue is currently clear. No unmapped additives flagged for review.</p>
            </div>
          ) : (
            <div className="audit-table-container">
              <table className="audit-table">
                <thead>
                  <tr>
                    <th>Timestamp</th>
                    <th>Product / Context</th>
                    <th>Unmapped Tokens</th>
                    <th>Confidence</th>
                    <th>Status</th>
                  </tr>
                </thead>
                <tbody>
                  {records.map((r, i) => (
                    <tr key={i}>
                      <td>{new Date(r.timestamp).toLocaleTimeString()}</td>
                      <td><strong>{r.context_identifier || "Direct Scan"}</strong></td>
                      <td>
                        {(r.unmapped_tokens || []).map((t, idx) => (
                          <span key={idx} className="badge badge-unmapped">{t}</span>
                        ))}
                      </td>
                      <td>{Math.round((r.parser_confidence || 0) * 100)}%</td>
                      <td><span className="badge badge-pending">Pending Review</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose}>Close</button>
        </div>
      </div>
    </div>
  );
}

export default AuditQueueModal;
